use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.get_board();
    var first = true;
    for dish in board {
        if !first {
            io.write(text: ";")?;
        }
        kitchen.serve(dish: dish)?;
        first = false;
    }
    return Ok(unit);
}

