use depot.locker;

fn report() -> String {
    let ax = locker.new(label: "ax");
    let bay = locker.new(label: "bay");
    let cod = locker.new(label: "cod");

    locker.stow(locker: ax, weight: 12);
    locker.stow(locker: ax, weight: 9);
    locker.stow(locker: bay, weight: 30);
    locker.stow(locker: bay, weight: 25);
    locker.stow(locker: cod, weight: 5);

    let ax_weight = locker.weight(locker: ax).to_text();
    let bay_weight = locker.weight(locker: bay).to_text();
    let cod_weight = locker.weight(locker: cod).to_text();

    "ax=".concat(other: ax_weight).concat(other: ",bay=").concat(other: bay_weight).concat(other: ",cod=").concat(other: cod_weight)
}

