use harbor.signal;

fn entries() -> String {
    let signals = signal.daily();
    var result = "";
    var first = true;
    for s in signals {
        let rendered = match s {
            Calm => "calm",
            Gale(speed) => "gale:".concat(speed.to_text()),
            Fog(density) => "fog:".concat(density),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(";").concat(rendered);
        }
    }
    return result;
}

