use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    for frame in frames {
        let value = match feed.decode(frame: frame) {
            Some(v) => v,
            None => 0,
        };
        total = total + value;
    }
    feed.emit(total: total, io: io)?;
    return Ok(unit);
}

